<script setup lang="ts">
import { onMounted, provide, ref } from "vue"; import { useRoute, useRouter } from "vue-router"; import { getCustomer, resendInvitation, type Customer } from "../api";
const route = useRoute(); const router = useRouter(); const customer = ref<Customer | null>(null); const error = ref(""); provide("customer", customer);
async function load(): Promise<void> { try { customer.value = await getCustomer(String(route.params.id)); } catch (reason) { error.value = (reason as Error).message; } } async function resend(): Promise<void> { await resendInvitation(String(route.params.id)); } onMounted(load);
</script>
<template><section v-if="customer" class="customer-detail"><p class="breadcrumb"><RouterLink :to="{ name: 'customers.list' }">Clientes</RouterLink> / {{ customer.displayName }}</p><header><div><p class="eyebrow">Cliente</p><h1>{{ customer.displayName }}</h1><span :class="['status-pill', customer.registrationStatus]">{{ customer.registrationStatus === "pending" ? "Pendiente" : "Completado" }}</span></div><div><button v-if="customer.registrationStatus === 'pending'" class="secondary" @click="resend">Reenviar invitacion</button><RouterLink class="button-link" :to="{ name: 'customers.edit', params: { id: customer.id } }">Editar</RouterLink></div></header><nav class="tab-nav"><RouterLink :to="{ name: 'customers.detail.general' }">General</RouterLink><RouterLink :to="{ name: 'customers.detail.billing' }">Facturacion</RouterLink><RouterLink :to="{ name: 'customers.detail.repairs' }">Reparaciones</RouterLink><RouterLink :to="{ name: 'customers.detail.notes' }">Notas</RouterLink></nav><RouterView /></section><p v-else class="feedback error">{{ error || "Cargando cliente..." }}</p></template>